require_once __DIR__.'/includes/functions.php';require_customer();$uid=(int)current_user()['id'];$items=get_cart_items($conn,$uid);if(!$items) {flash('Your cart is empty.','error');redirect('cart.php');}
$s=$conn->prepare('SELECT name,phone FROM users WHERE id=?');$s->bind_param('i',$uid);$s->execute();$profile=$s->get_result()->fetch_assoc();$subtotal=cart_subtotal($items);$delivery=delivery_charge($subtotal);render_header('Checkout');?>
<div class="page-heading"><span class="eyebrow">ALMOST THERE</span><h1>Checkout</h1><p class="muted">Delivery is currently available for PIN code 431005 only.</p></div>
<div class="checkout-layout"><form class="form-card checkout-form" method="post" action="<?=e(url('place_order.php'))?>"><?=csrf_field()?><h2>Delivery details</h2><label>Full name<input name="customer_name" required maxlength="120" value="<?=e($profile['name'])?>"></label><label>Phone number<input name="phone" required pattern="[0-9]{10,15}" value="<?=e($profile['phone'])?>"></label><label>Full delivery address<textarea name="address" required maxlength="500" rows="3" placeholder="House / building, street, landmark"></textarea></label><label>PIN code<input name="pincode" required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" value="431005"></label><h2>Payment method</h2><label class="choice"><input type="radio" name="payment_method" value="cod" checked><span><b>Cash on Delivery</b><small>Pay when your order arrives.</small></span></label><label class="choice"><input type="radio" name="payment_method" value="upi"><span><b>Online payment (UPI QR)</b><small>Order stays under admin payment review until verified.</small></span></label><button class="button full">Continue to place order</button><p class="muted tiny">Your order will be checked against stock and delivery availability on the server.</p></form><aside class="summary-card"><h2>Order summary</h2><?php foreach($items as $i):?><div><span><?=e($i['name'])?> × <?=$i['quantity']?></span><b><?=money((float)$i['price']*(int)$i['quantity'])?></b></div><?php endforeach;?><hr><div><span>Subtotal</span><b><?=money($subtotal)?></b></div><div><span>Delivery</span><b><?=money($delivery)?></b></div><hr><div class="summary-total"><span>Total</span><b><?=money($subtotal+$delivery)?></b></div></aside></div><?php render_footer();?>
